export const LESSONS = {
  "rook": {"title":"ルーク：縦横にどこまでも","text":["ルークは縦か横に何マスでも進める。ただし駒を飛び越えることはできない。","ルークは重い駒で、終盤で絶大な力を持つ。「キャスリング」にも参加する（これは後で学ぶ）。"]},
  "bishop": {"title":"ビショップ：斜線を飛ぶ","text":["ビショップは斜めに何マスでも進める。駒を飛び越えることはできない。","それぞれのビショップは一生ひとつの色のマスしか踏めない —— 開始時、明るいマスのビショップと暗いマスのビショップが一枚ずつある。"]},
  "queen": {"title":"クイーン：万能の大砲","text":["クイーン＝ルーク＋ビショップ。縦・横・斜めのどの方向にも何マスでも進める。駒を飛び越えることはできない。","最も強い駒だが、そのぶんただで交換されるのが最も痛い —— クイーンを早く出しすぎないこと。"]},
  "knight": {"title":"ナイト：L 字に跳ぶ","text":["ナイトは L 字に動く：まっすぐ二マス進んで直角に一マス（合計 8 方向）。","ナイトだけが他の駒を飛び越えられる。間に駒があっても止められない。"]},
  "king": {"title":"キング：一手に一マス","text":["キングはどの方向へも一マスだけ動ける。","キングは相手に攻撃されているマスへは入れない（自ら王手を受ける手は指せない）—— しっかり守ること。詰まされたら対局が終わる。"]},
  "pawn": {"title":"ポーン：進むのは前、取るのは斜め","text":["ポーンは前へ一マスずつ進み、後ろへは決して戻れない。","その駒の最初の一手に限り、二マス進むことも選べる。","取り方だけが特別で、斜め前の一マスにいる駒を取る。まっすぐ前の駒は取れない。"]},
  "promotion": {"title":"昇格：ポーンがクイーンになる","text":["ポーンが相手の一段目に到達したら、その場でクイーン・ルーク・ビショップ・ナイトのいずれかに昇格しなければならない（ポーンのままではいられず、キングにもなれない）。","ほとんどの場合はクイーン。ただしナイトに昇格して即チェックをかけたり、ステイルメイトを避けるためにルークやビショップを選ぶこともある。"]},
  "castle": {"title":"キャスリング：一手で二枚動く","text":["キングがルークの方へ横に二マス動き、ルークがキングの反対側へ跳び越える —— 一手でキングを安全にし、同時にルークを活用する。","条件：そのキングとそのルークが一度も動いていない、間に駒がない、キングがチェックされておらず、通過するマスにも到着するマスにも相手の利きがない。"]},
  "enpassant": {"title":"アンパッサン（通過捕獲）","text":["相手のポーンが最初の一手の特権で二マス進み、こちらのポーンの取れるマスを通り越した直後に限り、あたかも一マスしか進まなかったかのように斜めに取れる —— これがアンパッサン。","権利はその一手だけ。すぐ取らなければ永久に消える。"]},
  "values": {"title":"駒の価値：損な交換をしない","text":["よく使う価値：ポーン 1 ・ ナイト／ビショップ 3（軽い駒）・ ルーク 5 ・ クイーン 9。キングに値段はない —— 失えば負け。","交換の前に勘定する：3 のナイトで 5 のルークを取るのは得、クイーンでルークを取るのは大損。"]},
  "protect": {"title":"取る前に、守られていないかを見る","text":["取れる ≠ 取るべき。守られている駒を取れば、相手はすぐ取り返してくる。","手順にしよう：取る前に、その駒を守っている駒が何枚あるか数える。高い駒で守られた安い駒を取るのは、ほぼ必ず損になる。"]},
  "trade": {"title":"交換：どんなときに得か","text":["交換とは、こちらが一枚取り、相手が一枚取り返すこと。得かどうかは価値の引き算そのまま：**3 のナイトで 5 のルークなら 2 の得**、逆なら 2 の損。","気をつけるのは一点だけ：**取れることは、取るべきことではない**。取る前に一度見る —— 取ったあと、相手は取り返せるか。取り返せるなら、両方の点を勘定に入れる。","もう一つ経験則：**リードしているときはよく交換し、遅れているときは交換を避ける**。ルーク一枚多ければ、盤上の駒が減るほどそのルークの発言力が増す。"]},
  "defend": {"title":"攻撃された駒を助ける","text":["相手が指し終えたら、まず自問する：相手は何を狙ったか。自分の駒が攻撃されていないか。","攻撃された高い駒はすぐ処理する：逃がす、守りをつける、あるいは攻撃してきた駒そのものを取る。"]},
  "check": {"title":"チェックと、その受け方","text":["相手のキングを攻撃することを「チェック」という。チェックされた側は直ちに解消しなければならず、方法は三つだけ：キングが逃げる、駒で遮る、攻めている駒を取る。","「チェックを無視する」という選択肢は存在しない —— 画面も合法な受け方しか選ばせない。"]},
  "goal": {"title":"勝ちは「チェックメイト」であって、駒を取り尽くすことではない","text":["**相手の駒を全部取るのは目的ではないし、そもそも起こらない。** 目的はただ一つ、相手のキングを**チェックメイト**にすること —— キングが攻撃されていて（チェック）、しかも**逃げる・合駒する・取る**の三つがすべて塞がっている状態。","キングが実際に取られることはない。チェックメイトになった瞬間に対局が終わるからだ。だからキングには価値がつかず、交換にも出せない。","もう一つの結末が**引き分け**：自分の番なのに合法手がなくチェックもされていない（ステイルメイト）、詰ませるだけの駒がない、両者合意、などいくつかある。引き分けは半点ずつ —— 負けている側がしばしばこれで踏みとどまる。"]},
  "mate": {"title":"チェックメイト：対局の終わり","text":["チェックされていて、合法な受けが一つもない＝チェックメイト。対局はその場で終わり、詰ませた側の勝ち。","最もよく出る形の一つが「バックランク・メイト」：キングが自分のポーンに退路を塞がれ、重い駒が一段目でチェックをかける。","詰み形をもっと練習したい？　「モード → パズル」へ。一手詰め・二手詰めの問題集が待っている。"]},
  "stalemate": {"title":"ステイルメイト：大優勢でも引き分けになる","text":["手番なのに、チェックはされておらず、合法手が一つもない＝ステイルメイト。引き分けになる。","大優勢のときほど、うっかりこれで勝ちを逃す —— 詰ませ切るまで、相手のキングには必ず「合法な逃げ道」を残しておく。"]},
  "ladder": {"title":"二枚のルークのラダー・メイト","text":["二枚の重い駒（ルーク／クイーン）が交互に「線を封じる＋チェックする」を繰り返し、梯子を登るように相手のキングを一段ずつ端へ追い詰めて詰ませる —— 最も習得しやすい必殺の技術。","合言葉：一枚がキングの行き先を封じ、もう一枚が隣の線からチェックする。キングが一段下がったら、また一段登る。"]},
  "qrladder": {"title":"クイーンとルーク：端で締め上げる","text":["クイーン＋ルークのラダーは二枚ルークと同じ要領で、しかもクイーンの方が線を厳重に封じられる —— ただしその分うっかりステイルメイトになりやすい。詰ませ切るまでキングに逃げ道を残すこと。","ラダーは「キングを端へ追う」型の代表。次の四つのレッスンは発想を変える：**キングはもう端や隅にいる。そこから一手でどう網を閉じるか**。"]},
  "drill-queen": {"title":"クイーンで単騎のキングを詰ます（エンジン相手）","text":["キング＋クイーン対キング単騎は最も基本的な必勝形。手順は三つ：①クイーンを黒キングから「ナイトの距離」に保ち、少しずつ包囲を狭める。②自分のキングを近づける。③キングが到着したら端で詰ます。","「ナイトの距離」はステイルメイト避けの保険：クイーンはキングを閉じ込めつつ、最後の一マスまで奪ってしまうことがない。行き詰まったら上のバーの「ヒント」を。"]},
  "drill-rook": {"title":"ルークで単騎のキングを詰ます（エンジン相手）","text":["キング＋ルーク対キング単騎も必勝だが、足取りがより問われる：①ルークで一本の線を封じて柵にし、黒キングの動ける範囲を狭めていく。②自分のキングを近づけ、黒キングと正面からオポジションを取る。③オポジションが決まった瞬間、ルークのチェックが詰みになるか、柵をもう一段押し上げる。","このレッスンを終えれば、最も大切な二つの基本終盤を身につけたことになる —— 対エンジンの「初心者」で最初の一局を始めるか（わざと間違えてくれる、最初の一局のための設定）、パズルで詰み型を磨き続けよう。"]},
  "backrank": {"title":"バックランク・メイト：自分のポーンに閉じ込められる","text":["**実戦で最も多い詰み型で、しかもたいてい双方が気づかないうちに起こる。** キングが g1／g8 へキャスリングしたあと、前の三つのポーンが一つも動いていない —— それがキングの唯一の出口を塞いでいる。","そこへルークかクイーンが一段目に降りてチェックすると、キングは**上がれず**（ポーンが塞ぐ）**横にも逃げられず**（左右ともルークの利き）、それで詰み。駒を一枚も捨てずに終わる。","防ぐのも一手：**先にポーンを一つ突いておく**（多いのは h ポーン）。キングに「空気穴」を開けておくわけで、上級者は何もないときに何気なく突いておく。"]},
  "qkiss": {"title":"クイーンの密着メイト：寄せる、ただし支えが要る","text":["クイーンが相手のキングに**ぴたりと接して**チェックするのを「密着」という。クイーンはキングの周囲を一度に封じるので、キングは一マスも動けなくなることが多い。","鍵は**支え**。密着したクイーンは自分もキングの攻撃範囲に入るので、**そのマスを別の駒が守っていなければならない**。さもないと黒キングに一口で食べられ、クイーンをただで捨てただけになる。このレッスンで支えるのは h6 のビショップ —— 横から g7 をしっかり押さえている。","つまり密着メイトの確認事項は二つだけ：**クイーンは寄せられるか。そのマスは守られているか。** 両方「はい」なら詰み。前者だけなら、それはクイーンの献上。"]},
  "smother": {"title":"スマザード・メイト：ナイトの十八番","text":["キングが自分の駒に囲まれて身動きが取れないとき、一回のチェックがそのまま詰みになる —— ナイトだけが「駒を飛び越えてチェックできる」ので、この詰みはほぼナイトの専売特許。","定番の絵：キングが隅に縮こまり、周りは全部味方。そこへナイトが f7（または f2）へ跳んで決まり。"]},
  "tc-smother": {"title":"実戦のスマザードメイト：隅に追い込み、出口をふさぐ","text":["スマザードメイトの形は「詰みの型」で見た。実戦でその形がそのまま現れることは少ない —— ふつうはまず**王手でキングを隅へ追い込み**、相手自身の駒に出口をふさがせる。","この局面では黒のキングがすでに h8 にいて、g8 のルークと g7・h7 のポーンにぎっしり囲まれている。ナイトが大好きな形：Nf7 の一手で逃げ場がない。","見つけるための合図：**隅のキングが、味方の駒に囲まれている**。それを見たらナイトを探す。"]},
  "arabian": {"title":"アラビアン・メイト：ルークとナイトの名コンビ","text":["**ルーク＋ナイト**は詰ましの相性が最も良い組み合わせ。二枚の利きの形がまったく重ならず、ルークの届かない斜めの角をナイトが押さえるからだ。","標準の形：キングが隅にいて、**ナイトが隅から二マスの位置**（たとえばキング h8、ナイト f6）。この一枚だけで **g8** と **h7** を同時に見ている。そこへルークが h7 へ入ってチェック、そのルーク自身をナイトが守っている。","覚え方は簡単：**ナイトが先に二つの逃げ口を塞ぎ、ルークが最後に入ってチェック。** 順番を逆にするとルークがただで取られる。"]},
  "drill-bishops": {"title":"二枚のビショップで単騎のキングを詰ます（エンジン相手）","text":["二枚のビショップは二色のマスを支配し、キングと協力すれば相手のキングを**隅**へ追い込んで詰ませられる —— ただし追い込む先は、ビショップが利かせられる隅（どちらかのビショップと同じ色の隅）でなければならない。","手順：二枚のビショップを隣り合う斜線に並べて網を張り、キングが後ろから黒キングを一マスずつ隅へ押していく。"]},
  "fork": {"title":"フォーク：一枚で二つを攻める","text":["一つの駒が同時に二つの標的を攻めるのがフォーク —— 相手はどちらか一方しか救えない。","王手つきのフォークが最も厳しい：相手はまず王手に応じるしかなく、もう一方の標的はこちらのものになる。ナイトはフォークの名手（その攻撃は合駒で遮れない）。"]},
  "pin": {"title":"ピン：動けなくなった駒","text":["ある駒が動くと自分のキングがチェックに晒される場合、その駒は動かせない —— これが「ピン」。","完全にピンされた駒はクリックしても行き先が一つも光らない。不具合ではなく、ルールが許していない。外し方：キングをピンの線から動かす、線を別の駒で遮る、ピンしている駒を取る。"]},
  "skewer": {"title":"スキュアー：前をどかせて後ろを取る","text":["スキュアーはピンの裏返し。一本の線の**手前**にいる高い駒を攻めてどかせ、その**後ろ**の駒を取る。","最も厳しいのは前にキングがいる形 —— 王手！　キングは必ずどかねばならず、後ろの駒はこちらのものになる。"]},
  "tc-skewer": {"title":"実戦の串刺し：前にキング、後ろにクイーン","text":["串刺しは「前の大駒を攻めてどかせ、後ろの駒を取る」手筋。いちばん強いのは**前がキング**の場合：キングは王手に応じるしかなく、後ろの駒を守る者がいなくなる。","黒のキング e5 と黒のクイーン e8 は同じファイルに並んでいる。ルークが王手で e ファイルに乗れば、キングがどいたあとクイーンはあなたのもの。","串刺しの探し方：**相手のキングとクイーンが同じ線上にいないか見て**、次にその線に乗れる自分の駒があるかを見る。"]},
  "discovery": {"title":"ディスカバード・アタック：一枚どいて、後ろから撃つ","text":["一つの駒がどくことで、その**後ろ**の同じ線の駒が攻撃を開始する —— これがディスカバード・アタック。どいた駒自身も駒を取ったり 良いマスを占めたりできる。一手で二つの仕事。","最強なのはディスカバード・チェック：現れるのが**王手**の場合。相手は王手に応じるしかなく、どいた駒が奪ったものは取り返せない。"]},
  "remove": {"title":"守り駒の排除：守っている駒をそのまま取る","text":["守り駒をどかす方法は二つ。動かざるを得なくするか（デフレクション）、**そのまま取ってしまう**か。","駒を交換する前にもう一つ問う。いま取ろうとしているこの駒は、何を守っているのか。それが消えれば、守られていたものは自分のものだ。"]},
  "deflect": {"title":"デフレクション：守り駒を引き離す","text":["駒が安全なのは、多くの場合**別の駒がそれを守っている**からだ。取りたければ正面から当たる必要はない。まず守り駒をどかせばいい。","いちばん手っ取り早いのは王手。相手は必ず応じなければならず、守り駒は持ち場を離れる。守られていたものは、もう誰の担当でもなくなる。"]},
  "overload": {"title":"オーバーロード：一枚で二役はこなせない","text":["一枚で二つを守っている状態が**オーバーロード**。両方を見ているように見えて、片方に対応させれば、もう片方は崩れる。","相手の駒が二役を負っていたら、その片方を攻める。そちらは救えても、もう片方は救えない。"]},
  "tc-overload": {"title":"実戦の過負荷：片方を交換し、もう片方を取る","text":["黒のクイーンは d7 から e8 のルークと d5 のナイトを同時に守っている。**一枚の駒は二つの仕事をこなせない**：片方の持ち場で交換してしまえば、もう片方には手が回らない。","Rxe8+ で黒のクイーンに取り返させる —— e8 に来た瞬間、d5 のナイトは守り手を失う：Qxd5。","過負荷の解き方はいつも同じ順番：**守られている二つの標的のうち、王手になるほうを先に**攻め、それからもう片方を取る。"]},
  "decoy": {"title":"デコイ：来てほしいマスへ誘い込む","text":["デフレクションは駒を**追い払う**。デコイはその逆で、駒を**誘い寄せる** —— そこに立った瞬間に困るマスへ。","定番は王手の捨て駒。相手は取らざるを得ず、取った結果、王はちょうどナイトのフォークの位置に立つ。"]},
  "tc-decoy": {"title":"誘導 + フォーク：まずキングをおびき寄せる","text":["フォークが成り立つには、二つの標的がナイトの跳び先にいる必要がある。標的がいない？ なら**そこへ招き寄せる**。","黒のキングは g8、クイーンは d8、あなたのナイトは e5 —— f7 に跳べば h8 と d8 を同時に攻められる。だからまず Rh8+！ 黒のキングはルークを取るしかなく（f8 は a3 のビショップが押さえている）、h8 に着いた瞬間 Nxf7+ でキングとクイーンのフォーク。","ルーク一枚でクイーンとポーンを得る。これが**誘導の捨て駒**：手放した駒が、相手のキングをフォークの位置まで運んでくる。"]},
  "interfere": {"title":"インターフェア：守っている線を断つ","text":["守り駒は一本の線で標的を見ている —— 横・縦・斜めのいずれか。**その線の途中に駒を置けば**視線は切れ、標的は無防備になる。","割り込んだ駒はたいてい取られるので、味方に守らせるか、取る側の損の方が大きい形にする。"]},
  "tc-interference": {"title":"実戦の遮断：守り手の視線を切る","text":["黒のクイーンは b7 から遠く g7 を守っていて、あなたのクイーンはもう h6 にいる —— あと足りないのは、この第 7 ランクを**切る**ことだけ。","d5 のナイトはどこへ動いても開き王手になる（c4 のビショップが g8 をにらんでいる）。e7 か c7 へ跳べば、ナイトはちょうど b7 と g7 の間に立つ：黒のキングは h8 へ下がるしかなく、Qxg7 で詰み —— 黒のクイーンはナイトの向こう側で届かない。Nf6+ でもよい：ナイトが h7 を支え、Qxh7 で詰み。","遮断の本質：**守り手の線を見つけ、そこに駒を差し込む**。できれば王手つきで。"]},
  "tc-zwischenzug": {"title":"中間手：先に王手、取り返すのは後","text":["相手に駒を取られると、反射的に**すぐ取り返したく**なる。でも取り返す前に、相手が「応じるしかない」一手 —— たいていは王手 —— を差し挟めることがある。それが**中間手**。","ここでは黒のビショップが f3 の駒を取ったばかりで、あなたの c4 のビショップは b5 のポーンに狙われている。すぐ gxf3 と取り返すと bxc4 でビショップを失う。先に Bxf7+：どうせ助からないビショップを、ポーン一つ**プラス王手**に換える。黒は王手に応じるしかなく、そのあと落ち着いて gxf3。","合言葉：**取られたらすぐ取り返さず、まず王手になる手がないか見る**。"]},
  "cl-inter": {"title":"中間手：取り返す前に一手はさむ","text":["駒の交換はふつう「取って、取り返す」です。でも取り返す前に、相手が**必ず応じなければならない手**（チェックやクイーン当たり）があるなら、先にそれを指します。これが**中間手**です。","交換を読むときの習慣は、**取り返す番が来るたびに、もっと強い中間手がないか見ること**。一対一の交換が、ただ取りに変わることがよくあります。","前の二問は同じ局面です。まずチェックでルークを取り、それからもう一枚のルークを取り返します。最後の局面も、チェックが先で駒取りがあとです。"]},
  "po-trap": {"title":"退路のない駒は捕まる","text":["どんなに働いて見える駒でも、**退路がなければ**危険です。ポーン一つで攻めれば、それだけで取られてしまいます。","閉じ込められた駒を探すには、その駒が行けるマスを一つずつ見て、ポーンに見られているマス、味方がいるマスを消していきます。**一つも残らなければ、ポーンで攻めましょう。**","下の三つの局面で捕まるのは、どれもビショップです。"]},
  "cl-quiet": {"title":"静かな一手：チェックも駒取りもなしで勝つ","text":["強制手を全部見ても何もない？次は**静かな一手**を探します。チェックも駒取りもしないのに、相手が防げない狙いを残す手です。","何もしていないように見えるので、いちばん見落としやすい手です。見つけ方は逆から問うこと。**もし二手続けて指せるなら、二手目は何か？**そのための一手目を探します。","下の三題の答えはどれも静かな一手で、その裏に次の決め手が隠れています。"]},
  "cl-threat": {"title":"まず問う：相手は何を狙っているか","text":["相手が指した直後は、自分の計画を急がずに、**まず問います。この手は次に何をしたいのか？**","この三つの局面では、黒の答えはどれも同じ。g2 でのメイトです。ふさぐだけでは足りません —— **最善の受けは、同時に反撃にもなっています**。","狙いがわかったら候補手を挙げます。g2 を守りながら相手も攻められる手はどれか？"]},
  "cl-cands": {"title":"候補手：まず三つ挙げてから選ぶ","text":["いい手が見えるとすぐ指したくなる —— いちばんよくある癖です。強い人は指す前に、**考える価値のある手（候補手）をいくつか挙げ**、それから一つずつ比べます。","挙げるときは決まった順番で問います。チェックはあるか？取れる駒はあるか？狙いはあるか？普通の手はそのあとです。最初に目に入った手が最善とは限らず、負ける手のこともあります。","このレッスンの三つの局面は、どれも最初に浮かぶ手が間違いです。候補手を挙げてから選びましょう。"]},
  "cl-order": {"title":"強制手が先：チェック、駒取り、狙い","text":["相手の応手が少ないほど、読みは簡単になります。**チェック**には受けるしかなく、**駒取り**には取り返しを考えさせ、**狙い**には守らせる —— この三つを**強制手**といいます。","候補手を挙げる順番は、**チェック、駒取り、狙いの順**。三つとも最後まで見ます。駒をただで渡すチェックはいい手ではありません。","次の三題は、チェック、駒取り、狙いの順に勝つ局面です。"]},
  "cl-count": {"title":"取る前に数える：攻めは何回、守りは何回","text":["取る前に、その駒が何回攻められ、何回守られているかを数えます。**攻めの数が守りの数より多いときだけ、その駒を取り切れます**。","数えたら駒の価値も見ます。**いちばん安い駒から取る**のが原則です。ルークとナイトを交換したら、最後に取れても損です。","取り返す側も数えているので、最後の駒取りまで数え続けます。"]},
  "cl-checks": {"title":"チェックはすべて読む —— 捨てる手も","text":["チェックを挙げるとき、安全な手だけで止めてはいけません。**クイーンを取られる場所に出すチェックも読みます**。相手は取るしかなく、次の一手がメイトということがよくあります。","見分け方は簡単です。チェックの受け方が一つか二つしかないなら、その一つ一つを先まで読みます。どの道もメイトに行き着くなら、クイーンを捨てても得です。","このレッスンの二つは有名なメイトです。スマザードメイト（クイーンを g8 に捨て、ナイトで決める）と、バックランクメイト（クイーンを e8 に捨て、ルークで決める）。"]},
  "cl-mate": {"title":"連続チェック：メイトまで読み切る","text":["相手がキングしか動かせないとき、**連続チェック**はいちばん読みやすい変化です。毎回応手は一つか二つなので、メイトまで読み切れます。","このレッスンのメイトは三手。ルークを捨ててキングを h8 に呼び込み、クイーンでチェックし、g7 でメイト —— g7 は f6 のポーンが守っています。","**捨てる前に一本の変化を最後まで読みます**。途中で一度でも逃げられたら、捨てたルークはただ損です。"]},
  "cl-race": {"title":"手数を数える：ポーンの競走","text":["ポーンの競走を決めるのは感覚ではなく、**手数の数え方**です。自分のポーンは昇格まで何手？相手のポーンは何手？手番はどちら？","キングも走ることを忘れずに。**キングの一手で二つの仕事ができる**のです —— 相手のポーンを追いながら、自分のポーンを助ける。","一問目は有名なレティのスタディ。追いつけそうにないポーンも、キングが斜めに歩けば追いつけます。あとの二問は、数えてから指しましょう。"]},
  "cl-end": {"title":"最後まで読む：途中で止めない","text":["読みでいちばん多い間違いは、**途中で止めること**です。「クイーンを取られる —— だめだ。」でも二手先まで進めると、結論が逆になることがあります。","ルールは、**局面が静かになるまで読む**こと。チェックも、取れる駒も、残った狙いもなくなってから、駒の損得を数えます。","このレッスンは一本の変化です。ルークを d4 に置くと、黒はクイーンを取ります。そこで止めずに先を読みましょう。"]},
  "cl-replies": {"title":"相手の応手をすべて挙げる","text":["強制手を読むときは、相手の**合法な応手をすべて**挙げます。一つも漏らしてはいけません。漏らした一手こそ、相手の唯一の逃げ道ということがよくあります。","このレッスンは有名な「ギリシャの贈り物」。Bxh7+ でビショップを捨て、Ng5+ で追い、Qh5 でクイーンを出します。一手ごとに、まず黒の応手を数えましょう。","**チェックのあと、相手の応手はたいてい二つか三つ**。その一つ一つを最後まで読めば、捨て駒に確信が持てます。"]},
  "cl-guard": {"title":"守っているのは誰か：先に守り駒を取る","text":["狙いたい駒にひもがついている？まず**何が守っているのか**を見ます。その守り駒を取れば（あるいはそらせば）、もとの狙いは守りを失います。","読む順番は、目標を決め、守っている駒を数え、**先に守り駒を取れないか**を見ること。一つ取って、もう一つ取る、という形がよくあります。","前の二問は同じ局面の二手。最後の局面では、d8 のルークを守っているナイトを探しましょう。"]},
  "opening": {"title":"序盤の三原則","text":["原則その一：中央を取る —— d4／e4／d5／e5 の四マスが盤全体の要所で、駒は中央に近いほど利きが広い。","原則その二：軽い駒を早く出す —— まずナイトとビショップ。同じ駒を何度も動かさない。クイーンを早く出しすぎない。","原則その三：早めにキャスリング —— キングを隅にしまい、ついでにルークも働かせる（さきほど学んだキャスリングのこと）。"]},
  "op-firstmove": {"title":"第一手：一手で三つの仕事をする","text":["序盤の第一手はほぼ必ず **e4 か d4**。慣習だからではなく、この一手が同時に三つの仕事をするからだ：中央を取る、ビショップに斜線を開ける、クイーンに斜線を開ける。","開始局面で白の合法手は 20 通りあるが、**f1 のビショップと d1 のクイーンは一つも動けない** —— 自分のポーンに完全に塞がれている。e4 と一手進めた途端、ビショップには 5 マス、クイーンには 4 マスの行き先ができる。一手で大駒が二枚解放される。","端のポーン（a4 や h4）はそのどれもできない。中央に触れず、誰の道も開けず、そのうえ自分のキングの脇に穴を残す。"]},
  "op-knights": {"title":"ナイトは中央へ、端へは跳ばない","text":["「端のナイトは働かない」は古い格言だが、数で確かめられる：**何もない盤で、f3 のナイトは 8 マスへ行けるのに、h3 では 4 マスしかない** —— ちょうど半分。","だから序盤のナイトはほぼ必ず **Nf3 と Nc3**（黒なら Nf6、Nc6）。中央に近く、しかも中央のマスをきちんと睨む位置。","Na3 や Nh3 のような端のナイトは、利きが狭いうえに相手の中央も止められず、次の一手でまた動かす羽目になることが多い —— つまり一手損。"]},
  "op-tempo": {"title":"序盤では、同じ駒を二度動かさない","text":["序盤で競っているのは**どちらが先に駒を配置し終えるか**。一手指すたびに新しい駒を一枚盤に出して、初めて得をしたことになる。すでに出た駒を動かし直すのは、その場足踏みと同じ。","いちばんよくある損な取引が**追い回されること**：早く出しすぎて、しかも安全でない位置にいると、相手はこちらを攻めながら駒を出せる。こちらが一手逃げるたび、相手は一枚出す —— 三度逃げれば、相手は三枚多い。","だから駒を出す前に一言：**このマスに、この駒は居座れるか。** 居座れない位置に早く出すのは、手数をただで捨てるのと同じ。"]},
  "op-castle": {"title":"キャスリングを先延ばしにしない：中央が開けば、キングは真ん中が一番危ない","text":["序盤では中央のポーンが取り合いになり、e ファイルと d ファイルは遅かれ早かれ開く。**開いた瞬間、e1／e8 に残っているキングは相手のルークとクイーンの正面に立つことになる。**","だからキャスリングは「余裕ができたらやること」ではなく、序盤の三つの仕事のうち唯一はっきり期限のあるもの：**ふつうは最初の 10 手以内**。軽い駒が二、三枚出たら、もうキャスリングの頃合い。","逆も同じ。相手がなかなかキャスリングしないのを見たら、中央をこじ開ける算段をする —— そこが相手の一番の弱点だからだ。"]},
  "op-pawnmoves": {"title":"ポーンは突いたら戻せない","text":["すべての駒のうち、ポーンだけが**後ろへ戻れない**。他の駒は位置を間違えても戻せるが、ポーンの前進は永久 —— 通り過ぎたあとに残るマスは、その一局ずっと守れなくなる。","だから序盤のポーンは節約して使う。ふつうは**中央の一つか二つ**だけで、中央を取り、駒に道を開けるために突く。一つ余分に突けば、埋められない穴が一つ増える。","とくにキングの前のポーン。キャスリングのあと f・g・h の三つはキングの屋根で、気軽に一つ突けばそこから雨が漏る。"]},
  "op-italian": {"title":"はじめての定跡：イタリアン・ゲーム","text":["三原則をつないで指せば、それがもう一つの定跡になる。入門に最も向いているのが**イタリアン・ゲーム**：1.e4 e5 2.Nf3 Nc6 3.Bc4。","三手で三つの仕事、一手も無駄がない：**e4 が中央を取りビショップとクイーンを解放し、Nf3 が駒を出しつつ e5 を攻め、Bc4 が駒を出しつつ f7 を狙う**（黒のキング前で、キングだけが守っている急所）。黒が同じ形で応じれば、そのまま互角。","定跡は暗記しなくてよい。各手が何をしているかを覚えておけば、相手が違う手を指してきても三原則で対応できる。手順そのものを覚えたければ、パズルの「定跡」に ECO 順で 109 の主要変化が並んでいる。"]},
  "firstgame": {"title":"はじめての一局：スカラーズ・メイト","text":["序盤の原則をつないで一局にしてみる —— ついでに最も有名な序盤の罠「スカラーズ・メイト（四手詰め）」を知っておく。無防備な相手を 4 手で詰ませる手順。","仕掛けは二枚で f7 を挟み撃ちにすること（黒のキング前で、キングだけが守っている急所）。ただし覚えておくこと：相手が正しく応じれば（g6 ＋ Nf6 など）、早く出したクイーンの方が追い回される —— だからこれは「知っておく」ための手順であって、頼るためのものではない。"]},
  "square": {"title":"スクエア・ルール：ポーンに追いつけるか","text":["ポーンが最終段まで何手かかるか、その手数を一辺として、ポーンのいるマスから最終段の方向へ正方形を描く —— これがポーンの「スクエア」。","**守る側の手番なら**、キングがこの正方形に入れる限り必ず追いつく。入れなければポーンは必ず昇格する。一手ずつ読まなくても、正方形を描けば結論が出る。","攻める側にとっても同じこと：ポーンが一歩進むたび正方形は一回り縮み、相手のキングが締め出されることがある。"]},
  "opposition": {"title":"オポジション：先にどいた方が損をする","text":["二つのキングが同じ線上にあり、間がちょうど一マスで、どちらもそれ以上近づけない —— これを「オポジション（対抗）」という。","肝心なのは**手番の側が先にどかねばならない**こと。だから「オポジションを取る」とは、指す義務を相手に押しつけて自分が得をすることに他ならない。","キングとポーンの終盤の勝ち負けは、しばしばこの一手で決まる。キングがポーンの前に出るだけでは足りず、オポジションも取らねばならない。取れないときは、ポーンを一手動かして「手待ち」し、義務を相手へ返す。"]},
  "keysquares": {"title":"キー・スクエア：キングが正しく立てば、ポーンは必ず通る","text":["キングとポーン対キング単騎では、勝敗はポーンの速さではなく**キングが正しいマスに立てるか**で決まる。そのマスを「キー・スクエア」という。","ポーンが第 4 ランクを越えたあとは、キー・スクエアはその真正面の三マス。e5 のポーンなら d6・e6・f6 で、白キングがそのどれか一つを占めれば、どちらの手番であってもそのポーンは必ず昇格できる。","だから正しい手順は **まずキングをキー・スクエアへ送り、ポーンは最後に突く**。逆に先にポーンを突いてキングが後を追う形にすると、引き分けにしかならないことが多い。"]},
  "kingactive": {"title":"終盤では、キングが主力","text":["中盤ではキングを隠すが、終盤は正反対：駒があらかた交換されたあと、**キングは攻めにも守りにも使える強い駒であり、出さなければ一枚少ないまま指しているのと同じ**。","終盤のキングの働きは、ビショップ一枚を少し上回るくらい。自分のポーンを護送し、相手のポーンを止め、相手のキングを一マスずつ押しのける —— どれも他の駒には代われない仕事だ。","だから終盤で最初に浮かべるべきは、ポーンをどう突くかではなく、**自分のキングを今どこへ動かすか**。中央へ、ポーンの多い側へ、相手のパスト・ポーンが必ず通る道の上へ。"]},
  "eg-kingact": {"title":"キングが出陣する：終盤では主力の駒","text":["中盤ではキングは隠れるもの、終盤では**前線へ出ていく**もの。クイーンや大駒が消えれば、キングは盤上で最強の攻め駒になる。","このキングとポーンの終盤は双方のポーン数が同じで、勝つのは**先にキングを中央へ運んだ側**。最初の一歩は g1 のキングを外へ出し、e3、d4 へ向かわせること。","合言葉：**大駒を交換し終えたら、キングは真ん中へ歩く**。"]},
  "drill-pawn": {"title":"キングとポーンの終盤：昇格まで護送する（エンジン相手）","text":["キング＋ポーン対キング単騎は最も多い終盤。キングがポーンの**前**を歩いて道を開け、ポーンの前方のキー・スクエアを押さえて（相手キングとオポジションを取って）はじめてポーンが通る。","キングが先、ポーンはゆっくり。昇格できれば勝ち —— 相手キングを詰まらせてステイルメイトにしないよう注意。行き詰まったら上のバーの「ヒント」でエンジンの推奨手を見る。"]},
  "majority": {"title":"ポーンが多い側：止められていないポーンから突く","text":["片側のポーンが相手より多いことを「ポーン・マジョリティ」という。その値打ちは数の多さではなく、**そこからパスト・ポーンを一つ絞り出せる**ことにある。","突き方に順序がある：**正面に相手のポーンがいない方から突く**（「候補ポーン」と呼ぶ）。それは遮られずに進み、相手のポーンを動かさざるを得なくさせ、後続のポーンが続けるようになる。塞がれている方から突けば、自分で自分を詰まらせるだけ。","守る側も同じ一条：相手が候補ポーンを突き始めたとき、慌ててポーンでぶつけない —— ぶつけるのは往々にして相手の思う壺。"]},
  "pawntrade": {"title":"駒が多ければ駒を、少なければポーンを交換する","text":["終盤で最も実用的な交換の原則：**自分が多いときは駒を交換し、自分が少ないときはポーンを交換する**。","多い側が一組交換すれば、残った駒の比率はさらに開く —— 駒が満載の盤で一ポーン多くても大したことはないが、キングとポーンだけになればその一ポーンが勝敗そのものになる。少ない側は逆で、ポーンを消してしまえば相手の余分な一ポーンも無意味になる。","だから一ポーン多い終盤では交換できる駒はどんどん交換し、逆に一ポーン少ないなら自分のポーンにしがみつき、ルークやビショップの方を手放す。"]},
  "rookbehind": {"title":"ルークはパスト・ポーンの後ろへ","text":["ルークとポーンの終盤には、ほぼ外れない決まりがある：**ルークはパスト・ポーンの後ろに置く**。自分のポーンの後ろでも、相手のポーンの後ろでもよい。","理屈はこう。ポーンが一歩進むたび、後ろのルークの射程は変わらないのに、前で止めているルークの立てるマスはどんどん減る。**突く側は突くほど強くなり、止める側は止めるほど窮屈になる。**","だからパスト・ポーンを見たらまず一言：自分のルークはその後ろにいるか。相手のルークはどこにいるか。この一問がそのまま終盤の結論になることが多い。"]},
  "eg-cutoff": {"title":"遮断：相手のキングをポーンに近づけない","text":["ルークとポーンの終盤、最初に学ぶのはポーンを押すことではなく、**相手のキングを締め出す**こと。ルークをランクに横たえれば、キングは永遠にそこを越えられない。","ここでは黒のキングが e8 にいる。ルークが h7 に着けば第 7 ランクは丸ごとあなたのもの —— 黒のキングは最終ランクをうろつくしかなく、あなたのキングとポーンがゆっくり進む。","覚えておく：**まず遮断、それから押す**。遠くで切るほど、キングは無力になる。"]},
  "wrongbishop": {"title":"色違いビショップ：一枚多くても引き分け","text":["端のポーン（a か h）＋ビショップは終盤で最も有名な落とし穴：**ビショップが昇格マスを利かせられない色なら、守る側のキングがその隅に座り込むだけで引き分け** —— 丸ごと一枚多くても勝てない。","理由は単純。ポーンはその一本の端の線からしか昇格できず、昇格マスの色は固定される。ビショップは一色のマスしか歩けないので、色が合わなければそのマスには永久に触れられず、隅に座ったキングを追い出すこともできない。","だからこの形になったら真っ先に二つ見る：**昇格マスは何色か、自分のビショップは何色か**。逆に自分が守る側なら、その隅をめざして潜り込む。"]},
  "eg-rook7": {"title":"第 7 ランクのルーク：ポーンを取り、キングを閉じ込める","text":["終盤でルークが最も活躍する場所の一つが**相手の第 7 ランク**：たいてい動いていないポーンが並んでいて、相手のキングは最終ランクに押し込められている。","Rd7 のあと b7 のポーンは目の前、黒のキングも第 8 ランクに閉じ込められる。防ぐには黒はルークを受け身の守りに引き戻すしかない。","開いたファイルを見たら、まず考える：**この線を通って第 7 ランクまで行けないか？**"]},
  "drill-lucena": {"title":"ルセナ：ルークとポーンの終盤で橋を架ける","text":["「ルセナ」はルークとポーンの終盤で最も重要な**勝ち方**の技術：自分のキングがポーンの前で道を塞いでいて、相手のルークが後ろから王手を続けてくるとき、自分のルークを第 4 ランクに置いて**橋を架け**、王手を遮る。するとキングがどけて、ポーンが無事に昇格できる。","三手で覚える：①ルークをポーンの前方、第 4 ランクへ。②キングをポーンの前からどける。③相手が王手をかけたら、ルークを間に入れて遮る（これが「橋」）。"]},
  "drill-philidor": {"title":"フィリドール：ルークとポーンの終盤を引き分けに持ち込む","text":["終盤は勝つだけでなく、**守れる**ことがもっと大切。「フィリドール・ディフェンス」は一ポーン少ないときに引き分けへ持ち込む定番の技術：ルークを自陣の**第 3 ランク**に横たえると、相手のキングは越えて来られない。相手のポーンが第 3 ランクまで来た瞬間、ルークを一段目へ下げ、**背後から連続で王手**をかける。","このレッスンでは白を持ち、**一ポーン少ない**。目標は勝ちではなく**引き分けに持ち込むこと** —— ステイルメイト、駒不足、50 手進展なしのいずれも成功。"]},
  "eg-bvn": {"title":"ビショップ対ナイト：ビショップは遠くからナイトを閉じ込められる","text":["盤が開けていて両翼にポーンがあるとき、**ビショップはナイトより強い**：ビショップは一手で長い斜線を丸ごと支配するが、ナイトは翼を変えるのに何手もかかる。","さらにビショップはナイトを**閉じ込め**られる。h8 の黒のナイトの出口は g6 と f7 の二つだけ —— そしてこの二つは同じ斜線上にある。Bh5 の一手で両方をふさげる。あとはあなたのキングがゆっくり歩いて行って取る。","相手のナイトが端にいたら、まず出口の数を数え、次に**一枚のビショップで全部をにらめないか**を見る。"]},
  "eg-nvrp": {"title":"ナイト対端のポーン：隅にもぐり込めば引き分け","text":["ナイト一枚対端のポーン一つ。ナイトで守り切れる？ 守れる —— ただし一つ、奇妙な手を知っている必要がある。","b2 の黒のキングは b3 のナイトを追い払い、a1 で昇格しようとしている。Na1！ ナイトが昇格マスにもぐり込む：黒のキングが取れば（Kxa1）、あなたは Kc2、黒には**指せる手がない** —— ステイルメイト。取らなければ、ナイトはそこに居座るだけ。","終盤では「駒を守る」ことだけを考えない —— **局面をステイルメイトにできる駒は、生き残る駒より価値がある**。"]},
  "eg-rvminor": {"title":"ルーク対ナイト：キングから離れるほど危ない","text":["ルーク一枚対ナイト一枚はふつう引き分け —— **ナイトが自分のキングのそばにいる限り**。遠くの隅に追いやられると、ルークとキングの連携で閉じ込められてしまう。","a1 の黒のナイトの出口は b3 と c2 の二つだけ。Rb2！ ルークが b ファイルで b3 を、第 2 ランクで c2 を押さえる —— ナイトは一歩も動けず、次の手で取られる。","ナイトで守るときは**キングから離さない**。ルークで攻めるときは**まず閉じ込め、それから取る**。"]},
  "eg-qvp": {"title":"クイーン対第 7 ランクのポーン：王手でキングをポーンの前に立たせる","text":["相手のポーンが第 7 ランクまで来ている。クイーンでこれに勝つにはリズムがある：**黒のキングが自分のポーンの前（e1）に立たされるまで王手を続ける** —— その一手の間ポーンは動けず、あなたのキングが一歩近づく。","あとは繰り返し：王手、キングをポーンの前へ、自分のキングを一歩近づける —— あなたのキングが到着してポーンを取るまで。","さあ始めよう：d2 のキングに王手がかかる手なら、どれも良い出だし。"]},
  "eg-queen": {"title":"クイーンの終盤：王手のついでにポーンを取る","text":["クイーンの終盤で最も実用的な技術は**王手つきのポーン取り**：まず王手、キングがよけた瞬間、クイーンは通り道の守られていないポーンを取る。相手には反撃の時間がまったくない。","黒の a7 と h7 のポーンはどちらも守られていない。Qh5+ か Qa4+、キングがよければ次の手でポーンが落ちる。","クイーンの終盤で手を探す順番：**まず王手を探し、次にその王手のあとで何を取れるかを見る**。"]},
  "mg-plan": {"title":"序盤が終わったら、まず三つ問う","text":["序盤が終わった合図はこう：軽い駒が出そろい、キングはキャスリングを済ませ、二枚のルークの間に駒がない。ここから先に決まり文句はなく、あるのは三つの問いだけ。","一つ、キングは安全か —— 自分のも相手のも。二つ、自分の駒でいちばん働いていないのはどれか —— 最も窮屈な位置の駒、それが次に動かす駒。三つ、相手は何を狙っているか —— 直前の一手はどこを向いていたか。","中盤は「妙手をひねり出す」ことではなく、いちばん悪い駒の置き場所を変えること。妙手はその積み重ねから出てくる。"]},
  "mg-trade": {"title":"いつ交換すべきか","text":["交換は「五分五分」ではない。必ずどちらかに有利で、要はこちらがどちら側にいるか。","駒得しているときは駒を交換し、ポーンは交換しない：盤上の駒が減るほど、多い一枚が目立ち、最後にはそれ一枚が盤を歩き回る。駒損しているときは逆 —— 駒を残し、局面を複雑にする。","もう一つ：自分の駒が密集して身動きが取れないときは、自分から一、二枚交換して残りの駒に場所を空けてやる。"]},
  "mg-openfile": {"title":"オープン・ファイル：ルークの高速道路","text":["一本の縦線に双方のポーンが一つもなければ、それが「オープン・ファイル」。ルークは自陣の一段目ではほとんど役に立たないが、オープン・ファイルに乗った途端、相手の陣地まで一気に届く。","だからポーンを交換したあと最初にやることは、たいてい空いたばかりのその線にルークを回すこと。二枚のルークを同じ線に重ねればもっと強く、これを「ダブル・ルーク」という。","一言で：ポーンが道を開け、ルークが乗る。"]},
  "po-file": {"title":"オープンファイルを取り、ルークを重ねる","text":["ポーンが一つもないファイルを**オープンファイル**といいます。そこにいるルークは、相手の一段目や七段目まで一気に進めます。","**まずファイルを取り、次にルークを重ねる**。同じオープンファイルに並んだ二つのルークは力が倍になり、相手は両方を止めるのがむずかしくなります。","三つの局面で b・c・g のオープンファイルが一本ずつ。どれもルークを重ねます。"]},
  "mg-outpost": {"title":"アウトポスト：追い払われないマスにナイトを置く","text":["相手の左右両隣のファイルからポーンが消えていれば、そのマスにはもうポーンが来て追い払うことができない —— これが「アウトポスト」。","アウトポストに最も向くのはナイト。動きが遅いぶん、いったん据われば長く効き続けるし、駒を飛び越えられる唯一の駒でもある。ビショップやルークも居心地がよい。","アウトポストはポーンの形から探す。ポーンが欠けているところに、穴がある。"]},
  "po-outpost": {"title":"アウトポスト：追い払えないナイトの拠点","text":["**アウトポスト**とは、相手のポーンでは決して攻められず、自分のポーンが守っているマスのことです。ナイトはアウトポストが大好き —— そこからいくつもの方向を同時に攻めます。","アウトポストかどうかは、そのマスの両隣のファイルを見て決めます。そこに上がってきて攻められる相手のポーンが残っているか？残っていなければ、そのマスはこちらのものです。","三つの局面とも、ナイトがアウトポストに入った瞬間に何かを得ます。"]},
  "po-hole": {"title":"弱いマス：ポーンが二度と守れない穴","text":["ポーンは前にしか進めないので、後ろのマスを守れるポーンがいなくなると、そのマスは二度とポーンで守れません。そういうマスを**弱いマス**（穴）といいます。","黒の g ポーンが g6 に進むと、f6 を守れる黒ポーンはもういません。こちらのポーンが g5 にいれば、f6 のナイトをしっかり支えられます。**相手の穴にナイトを置けば、追い払われることはありません。**","三つの局面はどれも同じ穴 f6。ナイトがそこに入ると何を攻められるか見てみましょう。"]},
  "mg-pawns": {"title":"ポーン構造：ダブル・ポーン、孤立ポーン、穴","text":["ポーンは盤上で唯一後ろへ戻れない駒なので、ポーンが動いたあとに残る弱点は永久に残る。ポーン構造が読めれば、その一局の長期的な行き先が読める。","ダブル・ポーン：同じファイルに自分のポーンが二つ。前の一つが後ろの一つを塞ぎ、どちらも進みにくく、互いに助け合うこともできない。","孤立ポーン：左右のファイルに味方のポーンが一つもない。守ってくれるポーンがいないので大きな駒が張り付くしかなく、張り付いた駒はその分だけ他所で働けない。"]},
  "ps-doubled": {"title":"ダブルポーン：二つのポーンで一つ分の仕事","text":["c6 と c7 のポーンが同じファイルに重なっている。これが**ダブルポーン**。前のポーンが後ろをふさぎ、後ろのポーンは前を守れない —— 二つで一つ分しか働かず、しかも後ろのポーン（c7）はポーンで守ってもらえない。","黒はポーン一つ多いが、あなたのルークは d ファイルを駆け下りて第 7 ランクへ行ける：Rd7 で c7 の真上に乗る。","ポーンの数を数えるときは、**ダブルポーンと孤立ポーンは割り引いて**数える。"]},
  "ps-iqp": {"title":"孤立ポーン：突破するか、包囲されるか","text":["d4 のポーンの両隣、c ファイルにも e ファイルにも味方のポーンがない —— これが**孤立ポーン**。ポーンでは守れないが、その代わりにスペースと活発な駒を手に入れている。","孤立ポーンを持つ側の計画はただ一つ：**封鎖される前に突破する**。d4–d5！ ファイルと斜線を開き、駒を全部働かせる。","相手側の計画はその逆：d5 のマスをしっかり占め（孤立ポーンの前にナイトを置く）、それからじっくり包囲する。"]},
  "ps-hanging": {"title":"ハンギングポーン：c4 と d4 が並び立つ","text":["c4 と d4 のポーンが横に並び、その両側に味方のポーンがない —— これを**ハンギングポーン**と呼ぶ。並んでいる間は b5、c5、d5、e5 の一列を支配していて、とても強い。","弱点は**どちらかを動かさざるを得なくなる**こと：動いた瞬間に穴が空く。だから主導権のある側は、相手の圧力が強まる前に自分でタイミングを選んで進める：d5！ 局面を開く。","相手のハンギングポーンには駒を集めて圧力をかけ、動かざるを得なくさせる。自分が持っているなら、**駒が活発なうちに自分から押す**。"]},
  "mg-passer": {"title":"パスト・ポーン：ひとりでに育つ駒","text":["自分のポーンの前のファイルにも、左右のファイルの前方にも相手のポーンがいない —— それが「パスト・ポーン」。進み切ればクイーンになる。","パスト・ポーンは前へ行くほど価値が上がり、しかも相手に見張りを一枚残させる。つまり相手はよそでの戦いに一枚足りなくなる。","だから中盤で交換するときは一緒に勘定しておく：交換したあと、パスト・ポーンを持つのはどちらか。持っている側は終盤に入った時点で勝っていることが多い。"]},
  "po-major": {"title":"ポーンの多い翼でパスポーンを作る","text":["片方の翼で自分のポーンが相手より多ければ、そこで**パスポーン**を作れます。前にも両隣にも、止めたり取ったりできる相手のポーンがいないポーンです。","方法は**ポーンをポーンにぶつける**こと。多い側がポーンを突いて交換を迫り、最後に余った一つがパスポーンになります。**前に相手のポーンがいないポーンから先に突きます。**","エンディングでは、遠く離れたパスポーン一つが勝負を決めることがよくあります。"]},
  "po-behind": {"title":"ルークはパスポーンの後ろに","text":["パスポーンが進むとき、ルークはどこがいちばんいいか？**その後ろです。**後ろにいれば、ポーンが一歩進むたびにルークの利くラインが一歩長くなります。","ポーンの前にいるルークは、ポーンが進むほど窮屈になります。後ろから押せば、相手のルークが前をふさいでいてもポーンは進めます。","これを**タラッシュの法則**といいます。ルークはパスポーンの後ろに —— 自分のパスポーンでも、相手のパスポーンでも同じです。"]},
  "mg-attack": {"title":"キングサイドの攻め：まず集めて、それから撃つ","text":["攻めは一枚の駒が頑張ることではなく、頭数で決まる。決まりは素朴：キングのいる側に、こちらの駒が相手の守りの駒より多いこと。","だから本当の攻めは「駒を寄せる」ところから始まる —— 一手ごとにその方向へ一枚ずつ足していき、相手より多くなってから動く。二枚しかないのに突っ込めば、たいてい返り討ちに遭う。","相手のキング前のポーンがいったん動いたら（h6 や g6 など）、そこが取っ掛かりになる —— まさにそこで頭数を数える。"]},
  "po-kpend": {"title":"交換の判断：勝てるポーンエンディングへ","text":["**ポーンエンディングはいちばん読み切りやすいエンディングです**。駒がなくキングとポーンだけなので、勝ちか引き分けかを一手ずつ数えられることがよくあります。","だから交換の前に問います。交換したあとのポーンエンディングは、**数えて勝ちとわかる局面か？**見るのは二つ。どちらのキングが前に出ているか、どちらに**遠いパスポーン**（相手キングから遠く離れたパスポーン）があるか。","三つの局面で、ルーク交換、クイーン交換、もう一度ルーク交換 —— どれも勝ちのポーンエンディングになります。"]},
  "po-trade": {"title":"交換の判断：ビショップを消して、キングが入る","text":["小駒どうしの交換も同じで、まず交換後のポーンエンディングを数えます。**交換のあと、先に相手のポーンの中へ入り込めたキングが勝ちます。**","交換するもう一つの理由は、相手のビショップが危険なポーンを守ったり送り出したりしているとき。そのビショップを消せば、ポーンの面倒を見る駒がいなくなります。","三つの局面はどれもビショップ交換で、交換すれば勝ちのキングとポーンのエンディングです。"]},
  "ps-chain": {"title":"ポーンチェーン：土台を攻める","text":["黒のポーン e5 と d6 は斜めにつながった**ポーンチェーン**：e5 は d6 が守り、d6 は c7 が守る。チェーンで最も固いのは先頭（e5）、最ももろいのは**土台**。","だから先頭にぶつかるのではなく、土台をこじ開ける：c4–c5 で d6 を攻める。d6 がゆるめば、チェーン全体がゆるむ。","ポーンチェーンに対する計画は一つの問いに尽きる：**どのポーンが土台で、自分のどのポーンをそれにぶつけるか？**"]},
  "po-chain": {"title":"ポーンチェーンの向く側で攻める","text":["斜めにつながったポーンを**ポーンチェーン**といいます。チェーンの先が向いている側では、こちらのスペースが広い —— **だからチェーンの向く側で攻めます**。ポーンを突いて攻めることがよくあります。","白の d4–e5 や e3–f4–e5 のチェーンは、黒キングのいるキングサイドを向いています。f ポーンを突いてぶつけ、キングの前のラインを開け、クイーンとルークを呼び込みます。","三つの局面はどれも同じ向き。チェーンの先は e5 で、f ポーンが突進します。"]},
  "ps-break": {"title":"ポーンブレイク：相手の支点を突き崩す","text":["黒の e5 のポーンは陣形全体の**支点**：d6 のビショップはこれに支えられて立ち、中央もこれで持ちこたえている。","取ることはできない（fxe5 は d6 のビショップに取り返されて活発にさせるだけ）。でも**横からぶつける**ことはできる：f4–f5！ 黒のビショップとクイーンを閉じ込め、e5 をぽつんと孤立した標的に変える。","ポーンブレイクの目的はポーンを取ることとは限らない —— 多くは**構図を変える**ため：自分に有利なポーン構造に組み替える。"]},
  "ps-minority": {"title":"マイノリティアタック：二つのポーンで三つを攻める","text":["クイーンサイドであなたのポーンは a、b の二つ、相手は a、b、c の三つ —— それなのに攻めるのはあなたのほう。これが**マイノリティアタック**。狙いはポーンを取ることではなく、**弱点を作る**こと。","b4–b5 と押す！ 交換のあと、相手には孤立した c6 のポーンか、遅れたポーンが残る —— あなたのルークとナイトには中盤の間ずっとやることがある。","この計画は「カールスバッド構造」ではほぼ毎局使う。覚えておく価値がある。"]},
  "ps-bishops": {"title":"良いビショップと悪いビショップ：相手の良いほうを交換する","text":["ビショップは斜めに動くので、**自分のポーンと同じ色のマスにいるビショップは悪いビショップ** —— 味方のポーンにさえぎられる。黒の c8 のビショップの前には d5、e6 という白マスのポーンがあり、ほとんど動けない。","e7 のビショップは黒の**良いビショップ**で、黒マスを走り、あなたの d4、e5 をにらんでいる。あなたの g5 のビショップもちょうど黒マスのビショップ —— Bxe7 で交換すれば、黒にはポーンにふさがれた悪いビショップしか残らない。","交換の原則：**相手の良い駒を交換し、悪い駒を残してやる**。"]},
  "po-badb": {"title":"悪いビショップ：自分のポーンにふさがれる","text":["ビショップは一生、同じ色のマスしか動けません。自分のポーンの多くが**ビショップと同じ色のマス**にいると、ビショップは味方にふさがれます。これが**悪いビショップ**です。","対策の原則は、**相手のいい駒を交換し、悪いビショップを残させる**こと。そして自分のキングとナイトを反対の色のマスで進めれば、ビショップは決して届きません。","最後の局面では、黒ビショップの退路が自分のポーンにふさがれています。悪いビショップは捕まることさえあります。"]},
  "po-color": {"title":"色の弱点：ビショップがいなくなると","text":["黒が …g6 と突くと、f6・g7・h6 の黒マスは黒マスのビショップが頼りになります。**そのビショップがいなくなると、キングのまわりの黒マスは穴になります**。","攻め方は、自分のクイーン、ナイト、ポーンでその黒マスを占めること。f6 のポーン、h6 のナイト、g7 のクイーン —— おなじみのメイトの形です。","下の二つの局面では、どちらも黒に黒マスのビショップがなく、二手でメイトになります。"]},
  "po-prophy": {"title":"予防：まず相手の計画をつぶす","text":["**予防**は一つの考え方です。自分の手を指す前に、**相手が次にいちばんしたいことは何か**を考え、それをさせないようにします。","エンディングでよくある予防は、相手のポーンを固定して前進や交換をさせないこと、あるいは相手キングが行きたいマスを先に押さえることです。","三つのキングとポーンのエンディング。どれも「先にさせない」一手です。"]},
  "ps-space": {"title":"スペースの優位：急いで交換しない","text":["c4 と e4 の二つのポーンが d5 をがっちり押さえ、黒の駒は後ろ三段に押し込められている —— これが**スペースの優位**（この構造は「マロツィ・バインド」と呼ばれる）。","スペースを持つ側が最も恐れるのは**交換**：駒が減るほど、相手は窮屈さを感じなくなる。だから Nxc6 は逆効果。正しいのはナイトを c2 か b3 へ退くか、f3 で e4 を固め、締めつけを保つこと。","スペースが多いときは覚えておく：**駒を残して、じわじわ締める**。"]},
};
